def extract_grid_from_text(text, start_marker):
    """Extract a grid starting after 'start_marker'"""
    start_idx = text.find(start_marker)
    if start_idx == -1:
        return None

    i = start_idx + len(start_marker)
    rows = []
    count = 0
    while count < 27 and i < len(text):
        newline_pos = text.find('\n', i)
        if newline_pos == -1:
            break
        line = text[i:newline_pos]

        # Check if this is a row of numbers
        if line.strip() and all(c.isdigit() or c.isspace() for c in line.strip()):
            parsed = [int(x) for x in line.split()]
            if parsed:
                rows.append(parsed)
                count += 1

        if count >= 27:
            break
        i = newline_pos + 1

    return rows

