def extract_demo_grid(messages, marker_prefix):
    """Extract a demo grid from messages"""
    for msg in messages:
        content = msg.get('message', {}).get('content', [])
        if not content:
            continue

        for item in content:
            if 'text' in item:
                text = item['text']
                if marker_prefix in text:
                    idx = text.find(marker_prefix)
                    remaining = text[idx + len(marker_prefix):]

                    # Split by newlines and extract data lines
                    raw_lines = remaining.split('\n')[:40]
                    grid_rows = []
                    for line in raw_lines:
                        stripped = line.strip()
                        if stripped and all(c.isdigit() or c.isspace() for c in stripped):
                            parsed = [int(x) for x in stripped.split()]
                            if parsed and len(parsed) <= 15:
                                grid_rows.append(parsed)

                    return grid_rows

    return None

